using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class CustomBattleActionDescription : CustomBattleActionDescriptionSpecifics
{
	[SerializeField]
	private bool enableCustomActionDescritionID;

	[SerializeField]
	[ShowIf("enableCustomActionDescritionID")]
	private string customActionDescritionID;

	public string CustomActionDescritionID => customActionDescritionID;

	protected bool isOnBattleScene => GameScenesUtils.IsBattleScene();

	protected LocalizationManager localizationManager => ReferenceSingleton<LocalizationManager>.Instance;

	public virtual string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		return "";
	}

	protected virtual string GetRawLocalizedDescription(BattleAction battleAction)
	{
		return localizationManager.GetLocalizedString(battleAction.BaseBattleActionData.ActionIDDescription);
	}

	protected string GetAmountWithUnlockablesModification(string amountModified)
	{
		if (!(amountModified == EffectsValues.UNLOCKABLES_VALUE.ToString()))
		{
			return amountModified;
		}
		return localizationManager.GetLocalizedX();
	}

	protected int GetNumberToReplaceWithX()
	{
		return 9999999;
	}
}
